{"cards": [{"node_code": "N_7cebaf66ef7d7cf8", "definition": "研究机车司机在运行过程中对机车进行控制、驾驶及状态监控的技术与规程，涵盖正常工况下的操纵方法、驾驶技巧及人机交互界面操作。", "boundary": "本节点聚焦于“人”对机车的直接操作行为及常规驾驶技术。边界在于区分“常规操纵”与“特殊情况处理”：正常区段、车站的驾驶归本节点；故障、非正常行车条件下的应急操作归“特殊情况的操纵与处理”。若涉及操纵策略对能耗的影响，侧重驾驶技巧归本节点，侧重能耗优化算法归“燃料节约”。", "includes": ["机车牵引、制动、调速等常规操纵技术", "驾驶规程、标准化作业流程及驾驶台操作", "机车运行状态监控与司机操作规范"], "excludes": ["机车故障或异常工况下的应急处置（归入特殊情况的操纵与处理）", "机务段层面的调度指挥与计划编制（归入机务段机车调度）"], "sibling_distinctions": [{"other_code": "N_71803815d3f86f86", "rule": "区分依据为工况状态：本节点针对正常、标准工况下的驾驶操作；兄弟节点针对故障、事故或非标准条件下的应急处理与决策。"}, {"other_code": "N_1046d137ee7a3040", "rule": "区分依据为侧重点：本节点侧重操纵动作本身及驾驶规范；兄弟节点侧重通过操纵策略优化以降低能耗的经济性目标。"}], "cross_boundary_rule": "若内容涉及“节能驾驶”，若主要描述司机如何操作以省油，主挂载本节点；若主要分析能耗模型与优化策略，可关联燃料节约，但具体操作指导仍归本节点。"}, {"node_code": "N_118a4811a4da18d5", "definition": "研究机车在出段前、入段后及途中停留期间进行的检查、补给、清洁及简单维护作业，确保机车处于良好技术状态以投入运用。", "boundary": "本节点聚焦于机车运用过程中的“整备”环节，即非运行状态下的准备与恢复工作。边界在于区分“整备”与“检修”：日常检查、加油、加水、清洁归本节点；涉及部件拆解、故障修复、定期大修归“机务段、机车保养与检修”。整备是运用的一部分，旨在保障即时可用性。", "includes": ["机车出段前的技术检查与状态确认", "燃料、水、砂等消耗品的补给作业", "机车清洁、外观检查及整备作业流程管理"], "excludes": ["机车故障诊断、部件更换及定期检修（归入机务段、机车保养与检修）", "机车运行中的操纵与驾驶（归入机车操纵）"], "sibling_distinctions": [{"other_code": "N_4345e98b3364f6bb", "rule": "区分依据为作业深度与性质：本节点侧重运用前的准备与日常维护（整备）；兄弟节点侧重停机后的系统性保养、故障维修及大修（检修）。"}, {"other_code": "N_7cebaf66ef7d7cf8", "rule": "区分依据为机车状态：本节点针对机车静止或整备状态下的作业；兄弟节点针对机车运行状态下的驾驶操作。"}], "cross_boundary_rule": "若整备过程中发现故障，若仅为记录并上报，归本节点；若涉及现场简易修复或深入诊断，需关联检修节点，但整备流程本身归本节点。"}, {"node_code": "N_1046d137ee7a3040", "definition": "研究在机车运用过程中，通过优化操纵策略、运行组织及技术参数，降低燃料或电力消耗的技术与管理方法。", "boundary": "本节点聚焦于机车运用阶段的“经济性”目标，即节能降耗。边界在于区分“运用节能”与“设计节能”：通过司机操纵、调度优化实现的节能归本节点；通过改进机车结构、提高热效率实现的节能归“机车设计与计算”。若涉及具体驾驶技巧，侧重操作归“机车操纵”，侧重能耗指标归本节点。", "includes": ["机车节能驾驶策略与操纵优化方法", "燃料消耗定额管理、能耗统计与分析", "运行组织优化对能耗的影响及节能技术应用"], "excludes": ["机车动力系统的结构改进与热效率提升（归入机车设计与计算）", "机车燃料系统的检修与维护（归入机务段、机车保养与检修）"], "sibling_distinctions": [{"other_code": "N_7cebaf66ef7d7cf8", "rule": "区分依据为研究目标：本节点以“降低能耗”为核心目标，研究节能策略；兄弟节点以“安全、正点、规范”为核心目标，研究驾驶操作本身。"}, {"other_code": "N_391778b34bc14059", "rule": "区分依据为管理维度：本节点侧重技术层面的能耗控制；兄弟节点侧重管理流程、自动化系统及整体运用效率的管理。"}], "cross_boundary_rule": "若内容涉及“节能驾驶培训”，若侧重具体操作手法，主挂载机车操纵；若侧重能耗考核指标与策略制定，主挂载本节点。"}]}
